```python
import json
from pathlib import Path

ARQUIVO = Path(__file__).parent / "tarefas.json"


def carregar():
    if ARQUIVO.exists():
        return json.loads(ARQUIVO.read_text(encoding="utf-8"))
    return []


def salvar(tarefas):
    ARQUIVO.write_text(json.dumps(tarefas, ensure_ascii=False, indent=2), encoding="utf-8")


def main():
    tarefas = carregar()
    while True:
        print("\n1) Ver  2) Adicionar  3) Concluir  4) Sair")
        opcao = input("> ").strip()
        if opcao == "1":
            for i, t in enumerate(tarefas, start=1):
                print(f"{i}. {t}")
        elif opcao == "2":
            tarefas.append(input("Tarefa: ").strip())
            salvar(tarefas)
        elif opcao == "3":
            numero = int(input("Número: "))
            if 1 <= numero <= len(tarefas):
                print("Concluída:", tarefas.pop(numero - 1))
                salvar(tarefas)
        elif opcao == "4":
            break


if __name__ == "__main__":
    main()
```

As tarefas ficam em `tarefas.json`, na mesma pasta do programa.

